INSERT INTO verses (translation_id, book_id, chapter, verse, text, words_of_jesus) VALUES
('webster','GEN',1,1,'In the beginning God created the heaven and the earth.',NULL),
('webster','GEN',1,2,'And the earth was without form, and void; and darkness [was] upon the face of the deep: and the Spirit of God moved upon the face of the waters.',NULL),
('webster','GEN',1,3,'And God said, Let there be light: and there was light.',NULL),
('webster','GEN',1,4,'And God saw the light, that [it was] good: and God divided the light from the darkness.',NULL),
('webster','GEN',1,5,'And God called the light Day, and the darkness he called Night: and the evening and the morning were the first day.',NULL),
('webster','GEN',1,6,'And God said, Let there be a firmament in the midst of the waters, and let it divide the waters from the waters.',NULL),
('webster','GEN',1,7,'And God made the firmament; and divided the waters which [were] under the firmament from the waters which [were] above the firmament: and it was so.',NULL),
('webster','GEN',1,8,'And God called the firmament Heaven: and the evening and the morning were the second day.',NULL),
('webster','GEN',1,9,'And God said, Let the waters under the heaven be gathered into one place, and let the dry [land] appear: and it was so.',NULL),
('webster','GEN',1,10,'And God called the dry [land] Earth, and the collection of waters he called Seas: and God saw that it [was] good.',NULL),
('webster','GEN',1,11,'And God said, Let the earth bring forth grass, the herb yielding seed, [and] the fruit-tree yielding fruit after its kind, whose seed [is] in itself, upon the earth: and it was so.',NULL),
('webster','GEN',1,12,'And the earth brought forth grass, [and] herb yielding seed after its kind, and the tree yielding fruit, whose seed [was] in itself, after its kind: and God saw that it [was] good.',NULL),
('webster','GEN',1,13,'And the evening and the morning were the third day.',NULL),
('webster','GEN',1,14,'And God said, Let there be lights in the firmament of the heaven, to divide the day from the night: and let them be for signs, and for seasons, and for days, and years.',NULL),
('webster','GEN',1,15,'And let them be for lights in the firmament of the heaven, to give light upon the earth: and it was so.',NULL),
('webster','GEN',1,16,'And God made two great lights; the greater light to rule the day, and the lesser light to rule the night: [he made] the stars also.',NULL),
('webster','GEN',1,17,'And God set them in the firmament of the heaven, to give light upon the earth.',NULL),
('webster','GEN',1,18,'And to rule over the day, and over the night, and to divide the light from the darkness: and God saw that it [was] good.',NULL),
('webster','GEN',1,19,'And the evening and the morning were the fourth day.',NULL),
('webster','GEN',1,20,'And God said, Let the waters bring forth abundantly the moving creature that hath life, and fowl [that] may fly above the earth in the open firmament of heaven.',NULL),
('webster','GEN',1,21,'And God created great whales, and every living creature that moveth, which the waters brought forth abundantly after their kind, and every winged fowl after his kind: and God saw that [it was] good.',NULL),
('webster','GEN',1,22,'And God blessed them, saying, Be fruitful, and multiply, and fill the waters in the seas, and let fowl multiply in the earth.',NULL),
('webster','GEN',1,23,'And the evening and the morning were the fifth day.',NULL),
('webster','GEN',1,24,'And God said, Let the earth bring forth the living creature after his kind, cattle, and the creeping animal, and the beast of the earth after his kind: and it was so.',NULL),
('webster','GEN',1,25,'And God made the beast of the earth after his kind, and cattle after their kind, and every animal that creepeth upon the earth after his kind: and God saw that [it was] good.',NULL),
('webster','GEN',1,26,'And God said, Let us make man in our image, after our likeness: and let them have dominion over the fish of the sea, and over the fowl of the air, and over the cattle, and over all the earth, and over every creeping animal that creepeth upon the earth.',NULL),
('webster','GEN',1,27,'So God created man in his [own] image, in the image of God created he him; male and female created he them.',NULL),
('webster','GEN',1,28,'And God blessed them, and God said to them, Be fruitful, and multiply, and replenish the earth, and subdue it: and have dominion over the fish of the sea, and over the fowl of the air, and over every living animal that moveth upon the earth.',NULL),
('webster','GEN',1,29,'And God said, Behold, I have given you every herb bearing seed, which [is] upon the face of all the earth, and every tree, in which [is] the fruit of a tree yielding seed; to you it shall be for food.',NULL),
('webster','GEN',1,30,'And to every beast of the earth, and to every fowl of the air, and to every animal that creepeth upon the earth, in which [is] life, [I have given] every green herb for food: and it was so.',NULL),
('webster','GEN',1,31,'And God saw every thing that he had made, and behold, [it was] very good. And the evening and the morning were the sixth day.',NULL),
('webster','PSA',23,1,'A Psalm of David. The LORD [is] my shepherd; I shall not want.',NULL),
('webster','PSA',23,2,'He maketh me to lie down in green pastures: he leadeth me beside the still waters.',NULL),
('webster','PSA',23,3,'He restoreth my soul: he leadeth me in the paths of righteousness for his name''s sake.',NULL),
('webster','PSA',23,4,'Yes, though I walk through the valley of the shades of death, I will fear no evil: for thou [art] with me; thy rod and thy staff they comfort me.',NULL),
('webster','PSA',23,5,'Thou preparest a table before me in the presence of my enemies: thou anointest my head with oil; my cup runneth over.',NULL),
('webster','PSA',23,6,'Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the LORD for ever.',NULL),
('webster','PSA',117,1,'O praise the LORD, all ye nations: praise him, all ye people.',NULL),
('webster','PSA',117,2,'For his merciful kindness is great towards us: and the truth of the LORD [endureth] for ever. Praise ye the LORD.',NULL),
('webster','MAT',11,1,'And it came to pass when Jesus had made an end of commanding his twelve disciples, he departed thence to teach and to preach in their cities.',NULL),
('webster','MAT',11,2,'Now when John had heard in the prison the works of Christ, he sent two of his disciples,',NULL),
('webster','MAT',11,3,'And said to him, Art thou he that should come, or do we look for another?',NULL),
('webster','MAT',11,4,'Jesus answered and said to them, Go and show John again those things which ye hear and see:',NULL),
('webster','MAT',11,5,'The blind receive their sight, and the lame walk, the lepers are cleansed, and the deaf hear, the dead are raised, and the poor have the gospel preached to them.',NULL),
('webster','MAT',11,6,'And blessed is [he] to whom I shall not be the cause of his falling into sin.',NULL),
('webster','MAT',11,7,'And as they departed, Jesus began to say to the multitudes concerning John, What went ye out into the wilderness to see? a reed shaken with the wind?',NULL),
('webster','MAT',11,8,'But what went ye out to see? A man clothed in soft raiment? Behold, they that wear soft [clothing] are in kings'' houses.',NULL),
('webster','MAT',11,9,'But what went ye out to see? A prophet? yes, I say to you, and more than a prophet.',NULL),
('webster','MAT',11,10,'For this is [he] concerning whom it is written, Behold, I send my messenger before thy face, who shall prepare thy way before thee.',NULL),
('webster','MAT',11,11,'Verily, I say to you, among them that are born of women, there hath not risen a greater than John the Baptist: notwithstanding, he that is least in the kingdom of heaven, is greater than he.',NULL),
('webster','MAT',11,12,'And from the days of John the Baptist, until now, the kingdom of heaven suffereth violence, and the violent take it by force.',NULL),
('webster','MAT',11,13,'For all the prophets and the law prophesied until John.',NULL),
('webster','MAT',11,14,'And if ye will receive [it] , this is Elijah who was to come.',NULL),
('webster','MAT',11,15,'He that hath ears to hear, let him hear.',NULL),
('webster','MAT',11,16,'But to what shall I liken this generation? It is like to children sitting in the markets, and calling to their fellows,',NULL),
('webster','MAT',11,17,'And saying, We have piped to you, and ye have not danced; We have mourned to you, and ye have not lamented.',NULL),
('webster','MAT',11,18,'For John came neither eating nor drinking, and they say, He hath a demon.',NULL),
('webster','MAT',11,19,'The Son of man came eating and drinking, and they say, Behold, a man gluttonous, and a wine-bibber, a friend of publicans and sinners. But wisdom is justified by her children.',NULL),
('webster','MAT',11,20,'Then he began to upbraid the cities in which most of his mighty works had been done, because they repented not.',NULL),
('webster','MAT',11,21,'Woe to thee, Chorazin; woe to thee, Bethsaida: for if the mighty works which have been done in you had been done in Tyre and Sidon, they would have repented long ago in sackcloth and ashes.',NULL),
('webster','MAT',11,22,'But I say to you, It shall be more tolerable for Tyre and Sidon at the day of judgment, than for you.',NULL),
('webster','MAT',11,23,'And thou, Capernaum, which art exalted to heaven, shalt be brought down to hell: for if the mighty works which have been done in thee, had been done in Sodom, it would have remained until this day.',NULL),
('webster','MAT',11,24,'But I say to you, that it shall be more tolerable for the land of Sodom, in the day of judgment, than for thee.',NULL),
('webster','MAT',11,25,'At that time Jesus answered and said, I thank thee, O Father, Lord of heaven and earth, because thou hast hid these things from the wise and prudent, and hast revealed them to babes.',NULL),
('webster','MAT',11,26,'Even so, Father, for so it seemed good in thy sight.',NULL),
('webster','MAT',11,27,'All things are delivered to me by my Father; and no man knoweth the Son, but the Father; neither knoweth any man the Father, save the Son, and [he] to whomsoever the Son will reveal [him] .',NULL),
('webster','MAT',11,28,'Come to me, all [ye] that labor, and are heavy laden, and I will give you rest.',NULL),
('webster','MAT',11,29,'Take my yoke upon you, and learn from me: for I am meek and lowly in heart; and ye shall find rest to your souls.',NULL),
('webster','MAT',11,30,'For my yoke [is] easy, and my burden is light.',NULL),
('webster','MAT',17,1,'And after six days, Jesus taketh Peter, James, and John his brother, and bringeth them upon a high mountain apart.',NULL),
('webster','MAT',17,2,'And [he] was transfigured before them: and his face shone as the sun, and his raiment was white as the light.',NULL),
('webster','MAT',17,3,'And behold, there appeared to them Moses and Elijah talking with him.',NULL),
('webster','MAT',17,4,'Then answered Peter, and said to Jesus, Lord, it is good for us to be here: if thou wilt, let us make here three tabernacles; one for thee, and one for Moses, and one for Elijah.',NULL),
('webster','MAT',17,5,'While he was yet speaking, behold, a bright cloud overshadowed them: and behold, a voice out of the cloud, which said, This is my beloved Son, in whom I am well pleased: hear ye him.',NULL),
('webster','MAT',17,6,'And when the disciples heard [it] , they fell on their face, and were in great fear.',NULL),
('webster','MAT',17,7,'And Jesus came and touched them, and said, Arise, and be not afraid.',NULL),
('webster','MAT',17,8,'And when they had lifted up their eyes, they saw no man, save Jesus only.',NULL),
('webster','MAT',17,9,'And as they were descending the mountain, Jesus charged them, saying, Tell the vision to no man, until the Son of man be raised again from the dead.',NULL),
('webster','MAT',17,10,'And his disciples asked him, saying, Why then say the scribes, that Elijah must first come?',NULL),
('webster','MAT',17,11,'And Jesus answered and said to them, Elijah truly will first come, and restore all things:',NULL),
('webster','MAT',17,12,'But I say to you, that Elijah is come already, and they knew him not, but have done to him whatever they pleased: likewise will also the Son of man suffer by them.',NULL),
('webster','MAT',17,13,'Then the disciples understood that he spoke to them concerning John the Baptist.',NULL),
('webster','MAT',17,14,'And when they had come to the multitude, there came to him a [certain] man kneeling down to him, and saying,',NULL),
('webster','MAT',17,15,'Lord, have mercy on my son; for he is lunatic, and grievously distressed; for often he falleth into the fire, and often into the water.',NULL),
('webster','MAT',17,16,'And I brought him to thy disciples, and they could not cure him.',NULL),
('webster','MAT',17,17,'Then Jesus answered and said, O faithless and perverse generation, how long shall I be with you? how long shall I suffer you? bring him hither to me.',NULL),
('webster','MAT',17,18,'And Jesus rebuked the demon, and he departed out of him: and the child was cured from that very hour.',NULL),
('webster','MAT',17,19,'Then came the disciples to Jesus apart, and said, Why could not we cast him out?',NULL),
('webster','MAT',17,20,'And Jesus said to them, Because of your unbelief: for verily I say to you, If ye have faith as a grain of mustard-seed, ye shall say to this mountain, Remove hence to yonder place, and it shall remove; and nothing shall be impossible to you.',NULL),
('webster','MAT',17,21,'However, this kind goeth not out, but by prayer and fasting.',NULL),
('webster','MAT',17,22,'And while they abode in Galilee, Jesus said to them, The Son of man will be betrayed into the hands of men:',NULL),
('webster','MAT',17,23,'And they will kill him, and the third day he will be raised again: And they were exceedingly grieved.',NULL),
('webster','MAT',17,24,'And when they had come to Capernaum, they that received tribute -[money] , came to Peter, and said, Doth not your Master pay tribute?',NULL),
('webster','MAT',17,25,'He saith, Yes. And when he had come into the house, Jesus anticipated him, saying, What thinkest thou, Simon? from whom do the kings of the earth take custom or tribute? from their own children, or from strangers?',NULL),
('webster','MAT',17,26,'Peter saith to him, From strangers. Jesus saith to him, Then are the children free.',NULL),
('webster','MAT',17,27,'Notwithstanding, lest we should offend them, go thou to the sea, and cast a hook, and take the fish that first cometh up: and when thou hast opened his mouth, thou shalt find a piece of money: take that, and give to them for me and thee.',NULL),
('webster','JHN',3,1,'There was a man of the Pharisees named Nicodemus, a ruler of the Jews:',NULL),
('webster','JHN',3,2,'The same came to Jesus by night, and said to him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him.',NULL),
('webster','JHN',3,3,'Jesus answered and said to him, Verily, verily, I say to thee, Except a man be born again, he cannot see the kingdom of God.',NULL),
('webster','JHN',3,4,'Nicodemus saith to him, How can a man be born when he is old? can he enter the second time into his mother''s womb, and be born?',NULL),
('webster','JHN',3,5,'Jesus answered, Verily, verily, I say to thee, Except a man be born of water, and [of] the Spirit, he cannot enter into the kingdom of God.',NULL),
('webster','JHN',3,6,'That which is born of the flesh, is flesh; and that which is born of the Spirit, is spirit.',NULL),
('webster','JHN',3,7,'Marvel not that I said to thee, Ye must be born again.',NULL),
('webster','JHN',3,8,'The wind bloweth where it will, and thou hearest the sound of it, but canst not tell whence it cometh, and whither it goeth: so is every one that is born of the Spirit.',NULL),
('webster','JHN',3,9,'Nicodemus answered and said to him, How can these things be?',NULL),
('webster','JHN',3,10,'Jesus answered and said to him, Art thou a teacher of Israel, and knowest not these things?',NULL),
('webster','JHN',3,11,'Verily, verily, I say to thee, We speak what we know, and testify what we have seen; and ye receive not our testimony.',NULL),
('webster','JHN',3,12,'If I have told you earthly things, and ye believe not, how will ye believe if I tell you heavenly things?',NULL),
('webster','JHN',3,13,'And no man hath ascended to heaven, but he that came down from heaven, [even] the Son of man who is in heaven.',NULL),
('webster','JHN',3,14,'And as Moses lifted up the serpent in the wilderness, even so must the Son of man be lifted up:',NULL),
('webster','JHN',3,15,'That whoever believeth in him should not perish, but have eternal life.',NULL),
('webster','JHN',3,16,'For God so loved the world, that he gave his only-begotten Son, that whoever believeth in him, should not perish, but have everlasting life.',NULL),
('webster','JHN',3,17,'For God sent not his Son into the world to condemn the world, but that the world through him may be saved.',NULL),
('webster','JHN',3,18,'He that believeth on him, is not condemned: but he that believeth not, is condemned already, because he hath not believed in the name of the only-begotten Son of God.',NULL),
('webster','JHN',3,19,'And this is the condemnation, that light is come into the world, and men have loved darkness rather than light, because their deeds were evil.',NULL),
('webster','JHN',3,20,'For every one that doeth evil hateth the light, neither cometh to the light, lest his deeds should be reproved.',NULL),
('webster','JHN',3,21,'But he that doeth truth, cometh to the light, that his deeds may be made manifest, that they are wrought in God.',NULL),
('webster','JHN',3,22,'After these things came Jesus and his disciples into the land of Judea; and there he tarried with them, and baptized.',NULL),
('webster','JHN',3,23,'And John also was baptizing in Enon, near to Salim, because there was much water there: and they came, and were baptized.',NULL),
('webster','JHN',3,24,'For John was not yet cast into prison.',NULL),
('webster','JHN',3,25,'Then there arose a question between [some] of John''s disciples and the Jews, about purifying.',NULL),
('webster','JHN',3,26,'And they came to John, and said to him, Rabbi, he that was with thee beyond Jordan, to whom thou didst bear testimony, behold, the same baptizeth, and all [men] come to him.',NULL),
('webster','JHN',3,27,'John answered and said, A man can receive nothing, except it be given him from heaven.',NULL),
('webster','JHN',3,28,'Ye yourselves bear me testimony, that I said I am not the Christ, but that I am sent before him.',NULL),
('webster','JHN',3,29,'He that hath the bride, is the bridegroom: but the friend of the bridegroom, who standeth and heareth him, rejoiceth greatly, because of the bridegroom''s voice: this my joy therefore is fulfilled.',NULL),
('webster','JHN',3,30,'He must increase, but I [must] decrease.',NULL),
('webster','JHN',3,31,'He that cometh from above is above all: he that is of the earth is earthly, and speaketh of the earth: he that cometh from heaven is above all.',NULL),
('webster','JHN',3,32,'And what he hath seen and heard, that he testifieth; and no man receiveth his testimony.',NULL),
('webster','JHN',3,33,'He that hath received his testimony, hath set to his seal that God is true.',NULL),
('webster','JHN',3,34,'For he whom God hath sent, speaketh the words of God: for [to him] God giveth not the Spirit by measure.',NULL),
('webster','JHN',3,35,'The Father loveth the Son, and hath given all things into his hand.',NULL),
('webster','JHN',3,36,'He that believeth on the Son, hath everlasting life: and he that believeth not the Son, shall not see life; but the wrath of God abideth on him.',NULL),
('webster','3JN',1,1,'The elder to the well-beloved Gaius, whom I love in truth.',NULL),
('webster','3JN',1,2,'Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth.',NULL),
('webster','3JN',1,3,'For I rejoiced greatly, when the brethren came and testified of the truth that is in thee, even as thou walkest in the truth.',NULL),
('webster','3JN',1,4,'I have no greater joy than to hear that my children walk in truth.',NULL),
('webster','3JN',1,5,'Beloved, thou doest faithfully whatever thou doest to the brethren, and to strangers;',NULL),
('webster','3JN',1,6,'Who have borne testimony of thy charity before the church: whom if thou shalt bring forward on their journey after a godly sort, thou wilt do well:',NULL),
('webster','3JN',1,7,'Because for his name''s sake they went forth, taking nothing from the Gentiles.',NULL),
('webster','3JN',1,8,'We therefore ought to receive such, that we may be fellow-helpers to the truth.',NULL),
('webster','3JN',1,9,'I wrote to the church: but Diotrephes, who loveth to have the pre-eminence among them, receiveth us not.',NULL),
('webster','3JN',1,10,'Wherefore, if I come, I will remember his deeds which he doeth, prating against us with malicious words: and not content with that, neither doth he himself receive the brethren, and forbiddeth them that would, and casteth [them] out of the church.',NULL),
('webster','3JN',1,11,'Beloved, follow not that which is evil, but that which is good. He that doeth good is of God: but he that doeth evil hath not seen God.',NULL),
('webster','3JN',1,12,'Demetrius hath good report by all [men] , and by the truth itself: and we [also] bear testimony; and ye know that our testimony is true.',NULL),
('webster','3JN',1,13,'I had many things to write, but I will not with ink and pen write to thee:',NULL),
('webster','3JN',1,14,'But I trust I shall shortly see thee, and we shall speak face to face. Peace [be] to thee. [Our] friends salute thee. Greet the friends by name.',NULL),
('webster','REV',12,1,'And there appeared a great wonder in heaven; a woman clothed with the sun, and the moon under her feet, and upon her head a crown of twelve stars:',NULL),
('webster','REV',12,2,'And she being with child, cried, travailing in birth, and pained to be delivered.',NULL),
('webster','REV',12,3,'And there appeared another wonder in heaven; and behold, a great red dragon, having seven heads and ten horns, and seven crowns upon his heads.',NULL),
('webster','REV',12,4,'And his tail drew the third part of the stars of heaven, and cast them to the earth: and the dragon stood before the woman who was ready to be delivered, to devour her child as soon as it was born.',NULL),
('webster','REV',12,5,'And she brought forth a male child, who was to rule all nations with a rod of iron: and her child was caught up to God, and [to] his throne.',NULL),
('webster','REV',12,6,'And the woman fled into the wilderness, where she hath a place prepared by God, that they should feed her there a thousand two hundred [and] sixty days.',NULL),
('webster','REV',12,7,'And there was war in heaven: Michael and his angels fought against the dragon; and the dragon fought and his angels,',NULL),
('webster','REV',12,8,'And prevailed not; neither was their place found any more in heaven.',NULL),
('webster','REV',12,9,'And the great dragon was cast out, that old serpent, called the Devil, and Satan, which deceiveth the whole world: he was cast out upon the earth, and his angels were cast out with him.',NULL),
('webster','REV',12,10,'And I heard a loud voice saying in heaven, Now is come salvation, and strength, and the kingdom of our God, and the power of his Christ: for the accuser of our brethren is cast down, who accused them before our God day and night.',NULL),
('webster','REV',12,11,'And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives to the death.',NULL),
('webster','REV',12,12,'Therefore rejoice, [ye] heavens, and ye that dwell in them. Woe to the inhabiters of the earth, and of the sea! for the devil is come down to you, having great wrath, because he knoweth that he hath but a short time.',NULL),
('webster','REV',12,13,'And when the dragon saw that he was cast to the earth, he persecuted the woman who brought forth the male -[child] .',NULL),
('webster','REV',12,14,'And to the woman were given two wings of a great eagle, that she might fly into the wilderness, into her place, where she is nourished for a time, and times, and half a time, from the face of the serpent.',NULL),
('webster','REV',12,15,'And the serpent cast out of his mouth water as a flood after the woman, that he might cause her to be carried away by the flood.',NULL),
('webster','REV',12,16,'And the earth helped the woman, and the earth opened her mouth, and swallowed up the flood which the dragon cast out of his mouth.',NULL),
('webster','REV',12,17,'And the dragon was wroth with the woman, and went to make war with the remnant of her seed, who keep the commandments of God, and have the testimony of Jesus Christ.',NULL);
INSERT INTO verses_fts (verses_fts) VALUES ('rebuild');
